shell_commands:
node -e "
const l=require('./package-lock.json');
for (const [k,v] of Object.entries(l.packages)) {
  if (k.includes('ajv')) console.log(k, v.version, v.dev ? 'dev' : 'prod');
}
" && npm ls ajv 2>&1 | head -20

rm -rf dist; node -e "
const l=require('./package-lock.json');
for (const [k,v] of Object.entries(l.packages)) {
  if (k.includes('ajv')||k.includes('require-from-string')) console.log(k, v.version, v.dev?'dev':'prod');
}
"; git diff --stat package-lock.json; git status --porcelain

cat tsconfig.json; node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
try {
  ajv.compile({type: 'object', properties: {location: {type: 'not-a-json-schema-type'}}});
  console.log('NO THROW');
} catch (e) { console.log('THROWS:', e.message); }
const v = ajv.compile({type: 'object', properties: {location: {type: 'string'}, units: {type: 'string', enum: ['celsius','fahrenheit']}}, required: ['location']});
console.log('missing:', JSON.stringify(v({})));
console.log('wrongtype:', JSON.stringify(v({ssn: 123456789, location: 'x'})));
const w = ajv.compile({type:'object', properties:{ssn:{type:'string'}}, required:['ssn']});
console.log('wrongtype2:', JSON.stringify(w({ssn: 123456789})));
console.log('enum:', JSON.stringify(v({location:'x', units: 'kelvin'})));
console.log('valid:', w({ssn: 'abc', extra: 1}), 'validity only');
"

node --input-type=module -e "
import Ajv from 'ajv';
const ajv = new Ajv({strict: false, validateFormats: false});
const v = ajv.compile({type: 'object', properties: {ssn: {type: 'string'}, address: {type:'object', properties: {city: {type: 'string'}}}}, required: ['ssn']});
v({address: {city: 5}});
console.log(JSON.stringify(v.errors, null, 1));
const w = ajv.compile({type:'object', properties:{ssn:{type:'string'}}, required:['ssn','email']});
w({});
console.log(JSON.stringify(w.errors));
"
